const SIG = {};
SIG_RAW.trim().split('\n').forEach(line => {
  const [code, t, s, d, ing, st] = line.split('|');
  SIG[code] = { t: +t, s: +s, d: { e: 'easy', m: 'medium', h: 'hard' }[d], ing: ing.split(';').map(x => x.trim()), st: st.split(';').map(x => x.trim()) };
});
